import math, re, datetime as _dt

class TypError(Exception):
    def __init__(self, msg, span=None, hints=None):
        super().__init__(msg)
        self.msg = msg
        self.span = span  # (start, end) byte/char offsets in source if known
        self.hints = hints or []

class AutoType:
    def __repr__(self): return "auto"
AUTO = AutoType()

def is_int(v): return isinstance(v, int) and not isinstance(v, bool)
def is_num(v): return (isinstance(v, (int, float)) and not isinstance(v, bool))

class Length:
    __slots__=("pt","em")
    def __init__(self, pt=0.0, em=0.0): self.pt=float(pt); self.em=float(em)
    def __eq__(self, o): return isinstance(o, Length) and self.pt==o.pt and self.em==o.em
    def __hash__(self): return hash((self.pt,self.em))
    def resolve(self, font_size=11.0): return self.pt + self.em*font_size
class Ratio:
    __slots__=("v",)
    def __init__(self, v): self.v=float(v)  # 0.5 = 50%
    def __eq__(self,o): return isinstance(o,Ratio) and self.v==o.v
    def __hash__(self): return hash(self.v)
class Relative:
    __slots__=("ratio","length")
    def __init__(self, ratio, length): self.ratio=ratio; self.length=length
    def __eq__(self,o): return isinstance(o,Relative) and self.ratio==o.ratio and self.length==o.length
class Angle:
    __slots__=("deg",)
    def __init__(self, deg): self.deg=float(deg)
    def __eq__(self,o): return isinstance(o,Angle) and self.deg==o.deg
    def __hash__(self): return hash(self.deg)
class Fraction:
    __slots__=("v",)
    def __init__(self,v): self.v=float(v)
    def __eq__(self,o): return isinstance(o,Fraction) and self.v==o.v
    def __hash__(self): return hash(self.v)

class Label:
    __slots__=("name",)
    def __init__(self,name): self.name=name
    def __eq__(self,o): return isinstance(o,Label) and self.name==o.name
    def __hash__(self): return hash(("label",self.name))
class SymbolVal:
    __slots__=("text",)
    def __init__(self,text): self.text=text
    def __eq__(self,o): return isinstance(o,SymbolVal) and self.text==o.text
    def __hash__(self): return hash(("sym",self.text))
class BytesVal:
    __slots__=("data",)
    def __init__(self,data): self.data=bytes(data)
class DecimalVal:
    __slots__=("s",)
    def __init__(self,s): self.s=str(s)
class VersionVal:
    __slots__=("parts",)
    def __init__(self,parts): self.parts=tuple(int(x) for x in parts)
class RegexVal:
    __slots__=("pattern",)
    def __init__(self,pattern): self.pattern=pattern
class DatetimeVal:
    __slots__=("year","month","day","hour","minute","second")
    def __init__(self,year=None,month=None,day=None,hour=None,minute=None,second=None):
        self.year,self.month,self.day,self.hour,self.minute,self.second=year,month,day,hour,minute,second
    def to_date(self):
        try: return _dt.datetime(self.year or 1970,self.month or 1,self.day or 1,self.hour or 0,self.minute or 0,self.second or 0)
        except Exception: return None
class DurationVal:
    __slots__=("seconds",)
    # seconds total; also keep components as given for repr normalization done by typst (weeks/days/hours/minutes/seconds)
    def __init__(self,seconds=0.0): self.seconds=float(seconds)
class TypeVal:
    __slots__=("name",)
