    def __hash__(self): return hash(("type",self.name))
class SelectorVal:
    __slots__=("inner",)
    def __init__(self,inner): self.inner=inner

class Module:
    __slots__=("name","fields")
    def __init__(self,name,fields): self.name=name; self.fields=dict(fields)

class Content:
    __slots__=("func","fields")
    def __init__(self, func, fields=None):
        self.func=func
        self.fields=dict(fields or {})  # ordered
    def __repr__(self): return f"Content({self.func},{self.fields!r})"
    # helpers
    def text_content(self):
        if self.func=="text": return self.fields.get("text","")
        if self.func=="sequence": return "".join(c.text_content() for c in self.fields.get("children",[]) if isinstance(c,Content))
        if "body" in self.fields and isinstance(self.fields["body"],Content): return self.fields["body"].text_content()
        return ""

class Func:
    __slots__=("name","kind","fn","params","body","env","elem")
    def __init__(self, name, kind="builtin", fn=None, params=None, body=None, env=None, elem=None):
        self.name=name; self.kind=kind; self.fn=fn; self.params=params; self.body=body; self.env=env; self.elem=elem

# ---------- formatting ----------
def trim_num(x, digits=2):
    """Format with at most `digits` decimal places, trimming zeros (typst trimmed float)."""
    if x == 0: x = 0.0
    r = round(float(x), digits)
    if r == int(r) and abs(r) < 1e15:
        return str(int(r))
    s = f"{r:.{digits}f}".rstrip("0").rstrip(".")
    return s

def float_digits_exp(v):
    """Return (digits string, decimal exponent) for shortest repr: value = d[0].d[1:] * 10^exp"""
    if v == 0: return ("0", 0)
    s = repr(abs(v))
    # python repr may be decimal or scientific
    mant, exp = s, 0
    if "e" in s or "E" in s:
        mant, e = re.split("[eE]", s); exp = int(e)
    digits = mant.replace(".", "").lstrip("0")
    if "." in mant:
        intpart = mant.split(".")[0].lstrip("0")
        if intpart:
            exp = len(intpart)-1 + exp if False else exp  # placeholder
    # Recompute properly:
    # Use decimal string normalization via format with 'e'
    s2 = f"{abs(v):.15e}"  # not shortest
    # Instead derive from repr:
    if "e" in s or "E" in s:
        m, e = re.split("[eE]", s); e=int(e)
        digits = m.replace(".","").strip("0") or "0"
        # value = digits[0].digits[1:] *10^e  if mantissa had one digit before point
        return (digits, e)
    else:
        if "." in s:
            ip, fp = s.split(".")
        else:
            ip, fp = s, ""
        all_d = ip+fp
        # exponent = position of point -1 relative to first significant digit
        first_sig = None
        for i,ch in enumerate(ip):
            if ch != "0": first_sig=i; break
        if first_sig is not None:
            e = len(ip)-1-first_sig
            digits = (ip[first_sig:]+fp).rstrip("0") or "0"
            return (digits, e)
        else:
            # 0.000ddd
            cnt=0
            for ch in fp:
                if ch=="0": cnt+=1
                else: break
            e = -cnt-1
            digits = fp[cnt:].rstrip("0") or "0"
            return (digits, e)

def fmt_float_json(v):
    """serde_json / ryu style"""
    if math.isnan(v) or math.isinf(v): return "null"
    if v == 0: return "-0.0" if math.copysign(1,v)<0 else "0.0"
    digits, exp = float_digits_exp(v)
    sign = "-" if v < 0 else ""
    if exp < -5 or exp >= 16:
        if len(digits)==1: mant=digits
        else: mant=digits[0]+"."+digits[1:]
        return f"{sign}{mant}e{exp}"
    # decimal
    if exp >= 0:
        if len(digits) > exp+1:
            intpart=digits[:exp+1]; frac=digits[exp+1:]
            return f"{sign}{intpart}.{frac}"
        else:
            intpart=digits + "0"*(exp+1-len(digits))
            return f"{sign}{intpart}.0"
    else:
        return f"{sign}0.{'0'*(-exp-1)}{digits}"

def fmt_float_repr(v):
    """typst repr of float (python-repr like)"""
    if math.isnan(v): return "float.nan"
    if math.isinf(v): return "float.inf" if v>0 else "-float.inf"
    s = repr(float(v))
    if "e" in s:
        m,e = s.split("e"); e=int(e); return f"{m}e{e}"
    return s

def fmt_float_str(v):
    """str() conversion: Rust Display style, no exponent, no trailing .0, inf symbol handled by caller"""
    if math.isnan(v): return "NaN"
    if math.isinf(v): return "∞" if v>0 else "-∞"
    if v == 0: return "0"
    digits, exp = float_digits_exp(v)
    sign = "-" if v<0 else ""
    if exp >= 0:
        if len(digits) > exp+1:
            return f"{sign}{digits[:exp+1]}.{digits[exp+1:]}"
        else:
            return f"{sign}{digits}{'0'*(exp+1-len(digits))}"
    else:
        return f"{sign}0.{'0'*(-exp-1)}{digits}"

def fmt_length(l):
    if isinstance(l, Relative):
        parts=[]
        if l.ratio.v != 0: parts.append(fmt_ratio(l.ratio))
        if isinstance(l.length, Length):
            if l.length.pt != 0: parts.append(f"{trim_num(l.length.pt)}pt")
            if l.length.em != 0: parts.append(f"{trim_num(l.length.em)}em")
        if not parts: return "0%"
        return " + ".join(parts) if not (len(parts)==1 and parts[0].startswith("-")) else parts[0]
    if isinstance(l, Length):
        if l.em == 0: return f"{trim_num(l.pt)}pt"
        if l.pt == 0: return f"{trim_num(l.em)}em"
        # length with both pt and em prints like relative
        return fmt_length(Relative(Ratio(0), l))
    return str(l)

def fmt_ratio(r): return f"{trim_num(r.v*100)}%"
def fmt_angle(a): return f"{trim_num(a.deg)}deg"
def fmt_fraction(f): return f"{trim_num(f.v)}fr"

def escape_str(s):
    out=[]
    for ch in s:
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        else:
            o=ord(ch)
            if o < 0x20: out.append(f'\\u{{{o:x}}}')
            else: out.append(ch)
    return '"'+"".join(out)+'"'

TYPE_INFO = {}  # filled in lang for error messages

def type_name(v):
    if v is None: return "none"
    if isinstance(v, AutoType): return "auto"
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, float): return "float"
    if isinstance(v, str): return "str"
    if isinstance(v, list): return "array"
    if isinstance(v, dict): return "dictionary"
    if isinstance(v, Content): return "content"
    if isinstance(v, Length): return "length"
    if isinstance(v, Ratio): return "ratio"
    if isinstance(v, Relative): return "relative"
    if isinstance(v, Angle): return "angle"
    if isinstance(v, Fraction): return "fraction"
    if isinstance(v, Func): return "function"
    if isinstance(v, Module): return "module"
    if isinstance(v, TypeVal): return "type"
    if isinstance(v, Label): return "label"
    if isinstance(v, SymbolVal): return "symbol"
    if isinstance(v, BytesVal): return "bytes"
    if isinstance(v, DecimalVal): return "decimal"
    if isinstance(v, VersionVal): return "version"
    if isinstance(v, RegexVal): return "regex"
    if isinstance(v, DatetimeVal): return "datetime"
    if isinstance(v, DurationVal): return "duration"
    if isinstance(v, SelectorVal): return "selector"
    return "value"

DISPLAY_TYPE = {
    "int":"integer","str":"string","bool":"boolean","dictionary":"dictionary","array":"array",
    "content":"content","float":"float","length":"length","ratio":"ratio","angle":"angle",
    "fraction":"fraction","function":"function","module":"module","type":"type","label":"label",
    "symbol":"symbol","bytes":"bytes","decimal":"decimal","version":"version","regex":"regex",
    "datetime":"datetime","duration":"duration","selector":"selector","none":"none","auto":"auto",
    "relative":"relative length",
}
def dtype(v):
    if v is None: return "none"
    if isinstance(v, AutoType): return "auto"
    return DISPLAY_TYPE.get(type_name(v), type_name(v))

def repr_val(v, ctx=None):
    if v is None: return "none"
    if isinstance(v, AutoType): return "auto"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return fmt_float_repr(v)
    if isinstance(v, str): return escape_str(v)
    if isinstance(v, list):
        if not v: return "()"
        inner=", ".join(repr_val(x) for x in v)
        if len(v)==1: inner+=","
        return f"({inner})"
    if isinstance(v, dict):
        if not v: return "(:)"
        parts=[]
        for k,val in v.items():
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_-]*", str(k)): parts.append(f"{k}: {repr_val(val)}")
            else: parts.append(f"{escape_str(str(k))}: {repr_val(val)}")
        return "("+", ".join(parts)+")"
    if isinstance(v, Length) or isinstance(v, Relative): return fmt_length(v)
    if isinstance(v, Ratio): return fmt_ratio(v)
    if isinstance(v, Angle): return fmt_angle(v)
    if isinstance(v, Fraction): return fmt_fraction(v)
    if isinstance(v, Label): return f"<{v.name}>"
    if isinstance(v, SymbolVal): return f"symbol({escape_str(v.text)})"
    if isinstance(v, BytesVal): return f"bytes({len(v.data)})"
    if isinstance(v, DecimalVal): return f"decimal({escape_str(v.s)})"
    if isinstance(v, VersionVal): return "version("+", ".join(str(x) for x in v.parts)+")"
    if isinstance(v, RegexVal): return f"regex({escape_str(v.pattern)})"
    if isinstance(v, DatetimeVal):
        parts=[]
        if v.year is not None: parts.append(f"year: {v.year}")
        if v.month is not None: parts.append(f"month: {v.month}")
        if v.day is not None: parts.append(f"day: {v.day}")
        if v.hour is not None: parts.append(f"hour: {v.hour}")
        if v.minute is not None: parts.append(f"minute: {v.minute}")
        if v.second is not None: parts.append(f"second: {v.second}")
        return "datetime("+", ".join(parts)+")"
    if isinstance(v, DurationVal):
        total=v.seconds
        parts=[]
        # typst prints weeks/days/hours/minutes/seconds decomposition? When constructed with named args it keeps them normalized
        neg = total<0; total=abs(total)
        weeks=int(total//(7*86400)); rem=total-weeks*7*86400
        days=int(rem//86400); rem-=days*86400
        hours=int(rem//3600); rem-=hours*3600
        minutes=int(rem//60); secs=rem-minutes*60
        if weeks: parts.append(f"weeks: {weeks}")
        if days: parts.append(f"days: {days}")
        if hours: parts.append(f"hours: {hours}")
        if minutes: parts.append(f"minutes: {minutes}")
        if secs: parts.append(f"seconds: {trim_num(secs) if secs!=int(secs) else int(secs)}")
        return "duration("+", ".join(parts)+")"
    if isinstance(v, TypeVal):
        if v.name in ("none","auto"): return f"type({v.name})"
        return v.name
    if isinstance(v, Func):
        if v.kind=="closure": return "(..) => .."
        return v.name
    if isinstance(v, Module): return f"<module {v.name}>"
    if isinstance(v, SelectorVal): return repr_val(v.inner)
    if isinstance(v, Content):
        # repr of content: try reconstruct
        if v.func=="text": return f"[{v.fields.get('text','')}]"
        if v.func=="sequence":
            return "".join(repr_val(c) if not (isinstance(c,Content) and c.func=="text") else c.fields.get("text","") for c in v.fields.get("children",[]))
        # generic: name(body: ...) / name(field:..., body)
        parts=[]
        for k,val in v.fields.items():
            if k=="body" and isinstance(val,Content):
                parts.append(f"body: {repr_val(val)}")
            else:
                parts.append(f"{k}: {repr_val(val)}")
        if parts: return f"{v.func}("+", ".join(parts)+")"
        return v.func
    return str(v)

def display_val(v):
    """Display for interpolation into documents / str-like contexts."""
    if v is None: return ""
    if isinstance(v, AutoType): return "auto"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return fmt_float_str(v)
    if isinstance(v, str): return v
    if isinstance(v, Content): return v.text_content()
    if isinstance(v, (Length, Relative)): return fmt_length(v)
    if isinstance(v, Ratio): return fmt_ratio(v)
    if isinstance(v, Angle): return fmt_angle(v)
    if isinstance(v, Fraction): return fmt_fraction(v)
    if isinstance(v, Label): return f"<{v.name}>"
    if isinstance(v, SymbolVal): return v.text
    if isinstance(v, TypeVal): return repr_val(v)
    if isinstance(v, DatetimeVal): return repr_val(v)
    if isinstance(v, list): return ", ".join(display_val(x) for x in v)
    return repr_val(v)

def typ_eq(a,b):
    if isinstance(a,bool) or isinstance(b,bool):
        return type(a)==type(b) and a==b
    if is_num(a) and is_num(b): return float(a)==float(b)
    if type(a)!=type(b):
        # cross length/relative zero comparisons not critical
        return False
    if isinstance(a, Content):
        return a.func==b.func and list(a.fields.keys())==list(b.fields.keys()) and all(typ_eq(a.fields[k],b.fields[k]) for k in a.fields)
    if isinstance(a, list): return len(a)==len(b) and all(typ_eq(x,y) for x,y in zip(a,b))
    if isinstance(a, dict): return list(a.keys())==list(b.keys()) and all(typ_eq(a[k],b[k]) for k in a)
    if isinstance(a, DatetimeVal): return (a.year,a.month,a.day,a.hour,a.minute,a.second)==(b.year,b.month,b.day,b.hour,b.minute,b.second)
    if isinstance(a, DurationVal): return a.seconds==b.seconds
    if isinstance(a, VersionVal): return a.parts==b.parts
    if isinstance(a, BytesVal): return a.data==b.data
    if isinstance(a, DecimalVal): return a.s==b.s
    if isinstance(a, RegexVal): return a.pattern==b.pattern
    if isinstance(a, Func): return a is b
    if isinstance(a, Module): return a is b
    try: return a==b
    except Exception: return a is b

def to_jsonable(v):
    """Convert typst value to a Python structure suitable for json encoding with custom float handling.
    We return raw structures and encode with custom encoder below."""
    return v

def json_encode(v, pretty=False, indent=0):
    # Custom encoder mimicking serde_json via typst Value->JSON conversion
    sp = "  "*indent if pretty else ""
    sp2 = "  "*(indent+1) if pretty else ""
    nl = "\n" if pretty else ""
    if v is None: return "null"
    if isinstance(v, AutoType): return '"auto"'
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return fmt_float_json(v)
    if isinstance(v, str): return escape_str(v)
    if isinstance(v, list):
        if not v: return "[]"
        items=[json_encode(x,pretty,indent+1) for x in v]
        if pretty: return "["+nl+",\n".join(sp2+i for i in items)+nl+sp+"]"
        return "["+",".join(items)+"]"
    if isinstance(v, dict):
        if not v: return "{}"
        items=[]
        for k,val in v.items():
            key=escape_str(str(k))
            if pretty: items.append(f"{sp2}{key}: {json_encode(val,pretty,indent+1)}")
            else: items.append(f"{key}:{json_encode(val,pretty,indent+1)}")
        if pretty: return "{"+nl+",\n".join(items)+nl+sp+"}"
        return "{"+",".join(items)+"}"
    if isinstance(v, Content):
        # dict {"func": name, ...fields}
        d={"func": v.func}
        for k,val in v.fields.items(): d[k]=val
        return json_encode(d, pretty, indent)
    if isinstance(v, (Length, Relative)): return escape_str(fmt_length(v))
    if isinstance(v, Ratio): return escape_str(fmt_ratio(v))
    if isinstance(v, Angle): return escape_str(fmt_angle(v))
    if isinstance(v, Fraction): return escape_str(fmt_fraction(v))
    if isinstance(v, Label): return escape_str(f"<{v.name}>")
    if isinstance(v, SymbolVal): return escape_str(v.text)
    if isinstance(v, TypeVal):
        if v.name in ("none","auto"): return escape_str(f"type({v.name})")
        return escape_str(v.name)
    if isinstance(v, Func):
        if v.kind=="closure": return escape_str("(..) => ..")
        return escape_str(v.name)
    if isinstance(v, Module): return escape_str(f"<module {v.name}>")
    if isinstance(v, SelectorVal): return json_encode(v.inner, pretty, indent)
    # fallback: repr as string
    return escape_str(repr_val(v))

def yaml_encode(v, indent=0):
    """Approximate serde_yaml serialization of the JSON-converted value."""
    # Convert first to plain python (str/int/float/bool/None/list/dict) mirroring JSON conversion strings
    p = _to_plain(v)
    return _yaml_plain(p, indent)

def _to_plain(v):
    if v is None: return None
    if isinstance(v, AutoType): return "auto"
    if isinstance(v, bool): return v
    if isinstance(v, (int,float)): return v
    if isinstance(v, str): return v
    if isinstance(v, list): return [_to_plain(x) for x in v]
    if isinstance(v, dict): return {str(k): _to_plain(val) for k,val in v.items()}
    if isinstance(v, Content):
        d={"func": v.func}
        for k,val in v.fields.items(): d[k]=_to_plain(val)
        return d
    if isinstance(v, SelectorVal): return _to_plain(v.inner)
