    if r == int(r) and abs(r) < 1e15:
        return str(int(r))
    s = f"{r:.{digits}f}".rstrip("0").rstrip(".")
    return s

def float_digits_exp(v):
    """Return (digits string, decimal exponent) for shortest repr: value = d[0].d[1:] * 10^exp"""
    if v == 0: return ("0", 0)
    s = repr(abs(v))
    # python repr may be decimal or scientific
    mant, exp = s, 0
    if "e" in s or "E" in s:
        mant, e = re.split("[eE]", s); exp = int(e)
    digits = mant.replace(".", "").lstrip("0")
    if "." in mant:
        intpart = mant.split(".")[0].lstrip("0")
        if intpart:
            exp = len(intpart)-1 + exp if False else exp  # placeholder
    # Recompute properly:
    # Use decimal string normalization via format with 'e'
    s2 = f"{abs(v):.15e}"  # not shortest
    # Instead derive from repr:
    if "e" in s or "E" in s:
        m, e = re.split("[eE]", s); e=int(e)
        digits = m.replace(".","").strip("0") or "0"
        # value = digits[0].digits[1:] *10^e  if mantissa had one digit before point
        return (digits, e)
    else:
        if "." in s:
            ip, fp = s.split(".")
        else:
            ip, fp = s, ""
        all_d = ip+fp
        # exponent = position of point -1 relative to first significant digit
        first_sig = None
        for i,ch in enumerate(ip):
            if ch != "0": first_sig=i; break
        if first_sig is not None:
            e = len(ip)-1-first_sig
            digits = (ip[first_sig:]+fp).rstrip("0") or "0"
            return (digits, e)
        else:
            # 0.000ddd
            cnt=0
            for ch in fp:
                if ch=="0": cnt+=1
                else: break
            e = -cnt-1
            digits = fp[cnt:].rstrip("0") or "0"
