def fmt_float_json(v):
    """serde_json / ryu style"""
    if math.isnan(v) or math.isinf(v): return "null"
    if v == 0: return "-0.0" if math.copysign(1,v)<0 else "0.0"
    digits, exp = float_digits_exp(v)
    sign = "-" if v < 0 else ""
    if exp < -5 or exp >= 16:
        if len(digits)==1: mant=digits
        else: mant=digits[0]+"."+digits[1:]
        return f"{sign}{mant}e{exp}"
    # decimal
    if exp >= 0:
        if len(digits) > exp+1:
            intpart=digits[:exp+1]; frac=digits[exp+1:]
            return f"{sign}{intpart}.{frac}"
        else:
            intpart=digits + "0"*(exp+1-len(digits))
