def fmt_float_str(v):
    """str() conversion: Rust Display style, no exponent, no trailing .0, inf symbol handled by caller"""
    if math.isnan(v): return "NaN"
    if math.isinf(v): return "∞" if v>0 else "-∞"
    if v == 0: return "0"
    digits, exp = float_digits_exp(v)
    sign = "-" if v<0 else ""
    if exp >= 0:
        if len(digits) > exp+1:
            return f"{sign}{digits[:exp+1]}.{digits[exp+1:]}"
        else:
