def json_encode(v, pretty=False, indent=0):
    # Custom encoder mimicking serde_json via typst Value->JSON conversion
    sp = "  "*indent if pretty else ""
    sp2 = "  "*(indent+1) if pretty else ""
    nl = "\n" if pretty else ""
    if v is None: return "null"
    if isinstance(v, AutoType): return '"auto"'
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return fmt_float_json(v)
    if isinstance(v, str): return escape_str(v)
    if isinstance(v, list):
        if not v: return "[]"
        items=[json_encode(x,pretty,indent+1) for x in v]
        if pretty: return "["+nl+",\n".join(sp2+i for i in items)+nl+sp+"]"
        return "["+",".join(items)+"]"
    if isinstance(v, dict):
        if not v: return "{}"
        items=[]
        for k,val in v.items():
            key=escape_str(str(k))
            if pretty: items.append(f"{sp2}{key}: {json_encode(val,pretty,indent+1)}")
            else: items.append(f"{key}:{json_encode(val,pretty,indent+1)}")
        if pretty: return "{"+nl+",\n".join(items)+nl+sp+"}"
        return "{"+",".join(items)+"}"
    if isinstance(v, Content):
        # dict {"func": name, ...fields}
        d={"func": v.func}
        for k,val in v.fields.items(): d[k]=val
        return json_encode(d, pretty, indent)
    if isinstance(v, (Length, Relative)): return escape_str(fmt_length(v))
    if isinstance(v, Ratio): return escape_str(fmt_ratio(v))
    if isinstance(v, Angle): return escape_str(fmt_angle(v))
    if isinstance(v, Fraction): return escape_str(fmt_fraction(v))
    if isinstance(v, Label): return escape_str(f"<{v.name}>")
    if isinstance(v, SymbolVal): return escape_str(v.text)
    if isinstance(v, TypeVal):
        if v.name in ("none","auto"): return escape_str(f"type({v.name})")
        return escape_str(v.name)
    if isinstance(v, Func):
        if v.kind=="closure": return escape_str("(..) => ..")
        return escape_str(v.name)
    if isinstance(v, Module): return escape_str(f"<module {v.name}>")
    if isinstance(v, SelectorVal): return json_encode(v.inner, pretty, indent)
    # fallback: repr as string
    return escape_str(repr_val(v))

