    # Convert first to plain python (str/int/float/bool/None/list/dict) mirroring JSON conversion strings
    p = _to_plain(v)
    return _yaml_plain(p, indent)

def _to_plain(v):
    if v is None: return None
    if isinstance(v, AutoType): return "auto"
    if isinstance(v, bool): return v
    if isinstance(v, (int,float)): return v
    if isinstance(v, str): return v
    if isinstance(v, list): return [_to_plain(x) for x in v]
    if isinstance(v, dict): return {str(k): _to_plain(val) for k,val in v.items()}
    if isinstance(v, Content):
        d={"func": v.func}
        for k,val in v.fields.items(): d[k]=_to_plain(val)
        return d
    if isinstance(v, SelectorVal): return _to_plain(v.inner)
    # everything else becomes its repr string (except symbol -> text, label -> <x>)
    if isinstance(v, SymbolVal): return v.text
    if isinstance(v, Label): return f"<{v.name}>"
    if isinstance(v, TypeVal):
        return f"type({v.name})" if v.name in ("none","auto") else v.name
    if isinstance(v, Func): return "(..) => .." if v.kind=="closure" else v.name
    if isinstance(v, Module): return f"<module {v.name}>"
    if isinstance(v,(Length,Relative)): return fmt_length(v)
    if isinstance(v,Ratio): return fmt_ratio(v)
    if isinstance(v,Angle): return fmt_angle(v)
    if isinstance(v,Fraction): return fmt_fraction(v)
    return repr_val(v)

def _yaml_scalar(x):
    if x is None: return "null"
    if isinstance(x,bool): return "true" if x else "false"
    if isinstance(x,int): return str(x)
    if isinstance(x,float): return fmt_float_json(x) if fmt_float_json(x)!="null" else ".inf" if x>0 else "-.inf" if x<0 else ".nan"
    s=str(x)
    # serde_yaml: plain if safe
    if s=="" : return "''"
    if re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_ .,/()'-]*", s) and s.strip()==s and ": " not in s and " #" not in s and s.lower() not in ("null","true","false","yes","no","on","off","~"):
        # numbers-like strings must be quoted
        if re.fullmatch(r"-?\d+(\.\d+)?", s): return "'"+s+"'"
        return s
    # decide quoting
    if "\n" in s or "\t" in s:
        return escape_str(s).replace('\\u','\\x')  # approx
    # single quote style fallback using json double quotes - serde_yaml uses unquoted or single; acceptable
    return "'" + s.replace("'","''") + "'"

def _yaml_plain(p, indent):
    sp="  "*indent
    if isinstance(p, dict):
        if not p: return "{}"
        lines=[]
        for k,val in p.items():
            key=_yaml_scalar(str(k))
            if isinstance(val,(dict,list)) and val:
                lines.append(f"{sp}{key}:")
                lines.append(_yaml_plain(val, indent+1))
            elif isinstance(val,dict) and not val:
                lines.append(f"{sp}{key}: {{}}")
            elif isinstance(val,list) and not val:
                lines.append(f"{sp}{key}: []")
            else:
                lines.append(f"{sp}{key}: {_yaml_scalar(val)}")
        return "\n".join(lines)
    if isinstance(p, list):
        if not p: return "[]"
        lines=[]
        for item in p:
            if isinstance(item,(dict,list)) and item:
                sub=_yaml_plain(item, indent+1)
                # serde_yaml puts "- " with first line inline
                sublines=sub.split("\n")
                lines.append(f"{sp}- "+sublines[0].strip() if False else f"{sp}- "+sublines[0][len(sp)+2:])
                lines.extend(sublines[1:])
            elif isinstance(item,dict):
                lines.append(f"{sp}- {{}}")
            elif isinstance(item,list):
                lines.append(f"{sp}- []")
            else:
                lines.append(f"{sp}- {_yaml_scalar(item)}")
        return "\n".join(lines)
    return f"{sp}{_yaml_scalar(p)}"
