        node=("set",(self.base+start.start, self.toks[self.pos-1].end if self.pos else self.base+start.end), target, args)
        return node

    def parse_show(self):
        start=self.next()
        # parse selector expr until ':' at depth 0 - simple: parse expr, but colon isn't operator except dict/args, parse primary-ish
        # We parse an expression that stops before ':' - our parse_expr doesn't consume ':' so fine
        sel=self.parse_expr()
        self.skip_nl()
        if self.peek().kind!=":":
            t=self.peek(); raise TypError("expected colon", (self.base+t.start,self.base+t.end))
        self.next()
        transform=self.parse_expr_or_block()
        return ("show",(self.base+start.start, transform[1][1]), sel, transform)

    def parse_import(self, include):
        start=self.next()
        if include:
            expr=self.parse_expr()
            return ("include",(self.base+start.start,expr[1][1]),expr)
        expr=self.parse_expr()
        items=None; alias=None
        self.skip_nl()
        if self.peek().kind=="IDENT" and self.peek().val=="as":
            self.next(); alias=self.expect("IDENT").val
        elif self.peek().kind==":":
            self.next(); items=[]
            # items: ident, ident as alias, *
            while True:
                self.skip_nl()
                if self.peek().kind=="*": self.next(); items.append("*")
                else:
                    nm=self.expect("IDENT").val
                    al=None
                    if self.peek().kind=="IDENT" and self.peek().val=="as": self.next(); al=self.expect("IDENT").val
                    items.append((nm,al))
                self.skip_nl()
                if self.eat(","): continue
                break
        return ("import",(self.base+start.start,self.toks[self.pos-1].end),expr,items,alias)

    def parse_expr_or_block(self):
        self.skip_nl(); t=self.peek()
        if t.kind=="{":
            return self.parse_codeblock()
        return self.parse_expr()

    def parse_codeblock(self):
        open_tok=self.expect("{")
        stmts=self.parse_statements(end="}")
        close=self.expect("}")
        return ("block",(self.base+open_tok.start,self.base+close.end),stmts,False)

    # expression grammar
    def parse_expr(self):
        return self.parse_assign_expr()
    def parse_assign_expr(self):
        # closure detection handled in primary; just parse or-level
        return self.parse_or()
    def parse_or(self):
        left=self.parse_and()
        while True:
            self.skip_nl_save=None
            # 'or' keyword; but don't consume across newline for statement-level? inside expr allowed
            t=self.peek_nl_skip(0)
            if t.kind=="IDENT" and t.val=="or":
                # consume (with NLs)
                self.skip_nl(); self.next(); right=self.parse_and(); left=("bin",(left[1][0],right[1][1]),"or",left,right)
            else: break
        return left
    def parse_and(self):
        left=self.parse_compare()
        while True:
            t=self.peek_nl_skip(0)
            if t.kind=="IDENT" and t.val=="and":
                self.skip_nl(); self.next(); right=self.parse_compare(); left=("bin",(left[1][0],right[1][1]),"and",left,right)
            else: break
        return left
    def parse_compare(self):
        left=self.parse_add()
        while True:
            t=self.peek_nl_skip(0)
            op=None
            if t.kind in ("==","!=","<","<=",">",">="): op=t.kind
            elif t.kind=="IDENT" and t.val=="in": op="in"
            elif t.kind=="IDENT" and t.val=="not" and self.peek_nl_skip(1).kind=="IDENT" and self.peek_nl_skip(1).val=="in": op="not in"
            if not op: break
            self.skip_nl(); self.next()
            if op=="not in": self.skip_nl(); self.next()
            right=self.parse_add(); left=("bin",(left[1][0],right[1][1]),op,left,right)
        return left
    def parse_add(self):
        left=self.parse_mul()
        while True:
            t=self.peek()  # do not skip NL: binary across lines in parens handled elsewhere? skip spaces only (tokens have no spaces)
            # If next is + or - on same 'logical' position; NL tokens would appear - in args, lines can break before op rarely
            if t.kind in ("+","-"):
                # peek raw token without skipping NL: if NL before op, typst still allows in expressions inside brackets; treat as op if token is +/- 
                op=self.next().kind; right=self.parse_mul(); left=("bin",(left[1][0],right[1][1]),op,left,right)
            else: break
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while True:
            t=self.peek()
            if t.kind in ("*","/"):
                op=self.next().kind; right=self.parse_unary(); left=("bin",(left[1][0],right[1][1]),op,left,right)
            else: break
        return left
    def parse_unary(self):
        self.skip_nl(); t=self.peek()
        if t.kind in ("-","+"):
            self.next(); operand=self.parse_unary(); return ("un",(self.base+t.start,operand[1][1]),t.kind,operand)
        if t.kind=="IDENT" and t.val=="not":
            self.next(); operand=self.parse_unary(); return ("un",(self.base+t.start,operand[1][1]),"not",operand)
        return self.parse_postfix()
    def parse_postfix(self):
        expr=self.parse_primary()
        while True:
            t=self.peek()
            if t.kind==".":
                self.next()
                # method/field could be number? e.g. (1,2).0? no
                nt=self.peek()
                if nt.kind!="IDENT": raise TypError("expected identifier", (self.base+nt.start,self.base+nt.end))
                self.next(); expr=("field",(expr[1][0],self.base+nt.end),expr,nt.val)
                continue
            if t.kind=="(":
                args=self.parse_call_args_and_content(already_open=True)
                expr=("call",(expr[1][0],args[2]),expr,args)
                continue
            if t.kind=="CONTENT":
                ct=self.next(); content_node=("content",(self.base+ct.start,self.base+ct.end),ct.val[0],ct.val[1])
                # content block as trailing arg to a call/expression: if expr is ident/call/field => add to args
                if expr[0] in ("ident","field"):
                    expr=("call",(expr[1][0],content_node[1][1]),expr, ([],{},[content_node], content_node[1][1]))
                elif expr[0]=="call":
                    expr[3][2].append(content_node)
                else:
                    # applying content to non-function handled at eval
                    expr=("call",(expr[1][0],content_node[1][1]),expr, ([],{},[content_node], content_node[1][1]))
                continue
            break
        return expr
    def parse_call_args_and_content(self, already_open=False):
        # returns (pos, named, contents, end_offset_base)
        # current token expected '('
        open_tok=self.expect("(")
        pos=[]; named={}
        self.skip_nl()
        if not self.eat(")"):
            while True:
                self.skip_nl()
                if self.peek().kind=="..":
                    st=self.next(); e=self.parse_expr(); pos.append(("spread",e))
                elif self.peek().kind=="IDENT" and self.peek_nl_skip(1).kind==":":
                    name=self.next().val; self.skip_nl(); self.expect(":")
                    val=self.parse_expr(); named[name]=val
                elif self.peek().kind=="STR" and self.peek_nl_skip(1).kind==":":
                    name=self.next().val; self.skip_nl(); self.expect(":")
                    val=self.parse_expr(); named[name]=val
                else:
                    pos.append(self.parse_expr())
                self.skip_nl()
                if self.eat(","):
                    self.skip_nl()
                    if self.peek().kind==")": break
                    continue
                break
            self.expect(")")
        end=self.base+self.toks[self.pos-1].end
        contents=[]
        while self.peek().kind=="CONTENT":
            ct=self.next(); contents.append(("content",(self.base+ct.start,self.base+ct.end),ct.val[0],ct.val[1]))
            end=self.base+ct.end
        return (pos,named,contents,end)
    def parse_primary(self):
        self.skip_nl(); t=self.peek()
        if t.kind=="NUM": self.next(); return ("lit",(self.base+t.start,self.base+t.end),t.val)
        if t.kind=="STR": self.next(); return ("lit",(self.base+t.start,self.base+t.end),t.val)
        if t.kind=="RAW":
            self.next(); raw,block,lang=t.val
            fields={"text":raw}
            if block: fields["block"]=True
            else: fields["block"]=False
            if lang: fields["lang"]=lang
            if not block and "block" in fields:
                pass
            return ("rawcontent",(self.base+t.start,self.base+t.end),fields)
        if t.kind=="MATH":
            self.next(); return ("math",(self.base+t.start,self.base+t.end),t.val)
        if t.kind=="CONTENT":
            self.next(); return ("content",(self.base+t.start,self.base+t.end),t.val[0],t.val[1])
        if t.kind=="{":
            return self.parse_codeblock()
        if t.kind=="(":
            return self.parse_paren_or_closure()
        if t.kind=="<":
            # label
            self.next()
            nt=self.peek()
            if nt.kind=="IDENT":
                self.next()
                gt=self.peek()
                if gt.kind==">": self.next(); return ("lit",(self.base+t.start,self.base+gt.end),Label(nt.val))
                raise TypError("unclosed label", (self.base+t.start,self.base+nt.end))
            raise TypError("unclosed label", (self.base+t.start,self.base+t.end))
        if t.kind=="IDENT":
            w=t.val
            if w=="true": self.next(); return ("lit",(self.base+t.start,self.base+t.end),True)
            if w=="false": self.next(); return ("lit",(self.base+t.start,self.base+t.end),False)
            if w=="none": self.next(); return ("lit",(self.base+t.start,self.base+t.end),None)
            if w=="auto": self.next(); return ("lit",(self.base+t.start,self.base+t.end),AUTO)
            if w=="if": return self.parse_if()
            if w=="for": return self.parse_for()
            if w=="while": return self.parse_while()
            if w=="context":
                self.next(); body=self.parse_expr_or_block(); return ("context",(self.base+t.start,body[1][1]),body)
            if w in ("let","set","show"):
                raise TypError(f"unexpected keyword `{w}`", (self.base+t.start,self.base+t.end))
            if w in ("break",):
                # handled in statement; here expression context
                self.next(); return ("break",(self.base+t.start,self.base+t.end))
            if w in ("continue",):
                self.next(); return ("continue",(self.base+t.start,self.base+t.end))
            if w in ("return",):
                self.next(); e=self.parse_expr(); return ("return",(self.base+t.start,e[1][1]),e)
            if w=="else":
                raise TypError("unexpected keyword `else`", (self.base+t.start,self.base+t.end))
            # identifier possibly closure x => ...
            self.next()
            if self.peek().kind=="=>":
                self.next(); body=self.parse_expr_or_block()
                return ("closure",(self.base+t.start,body[1][1]),[(w,None,"pos")],body)
            return ("ident",(self.base+t.start,self.base+t.end),w)
        if t.kind=="}":
            raise TypError("unexpected closing brace", (self.base+t.start,self.base+t.end))
        if t.kind=="EOF":
            raise TypError("expected expression", (self.base+t.start,self.base+t.end))
        if t.kind==",":
            raise TypError("unexpected comma", (self.base+t.start,self.base+t.end))
        if t.kind=="=":
            raise TypError("unexpected equals sign", (self.base+t.start,self.base+t.end))
        if t.kind=="*":
            raise TypError("unexpected star", (self.base+t.start,self.base+t.end))
        if t.kind==":":
            raise TypError("unexpected colon", (self.base+t.start,self.base+t.end))
        if t.kind=="#":
            raise TypError("the character `#` is not valid in code", (self.base+t.start,self.base+t.end), hints=["you are already in code mode","try removing the `#`"])
        raise TypError("expected expression", (self.base+t.start,self.base+t.end))
    def parse_paren_or_closure(self):
        open_tok=self.expect("(")
        start=self.base+open_tok.start
        self.skip_nl()
        if self.peek().kind==")":
            cp=self.next()
            node=("lit",(start,self.base+cp.end),[])
            # closure () => ?
            if self.peek().kind=="=>":
                self.next(); body=self.parse_expr_or_block(); return ("closure",(start,body[1][1]),[],body)
            return node
        if self.peek().kind==":":
            self.next(); cp=self.expect(")")
            return ("lit",(start,self.base+cp.end),{})
        items=[]; is_dict=False
        while True:
            self.skip_nl()
            if self.peek().kind=="..":
                st=self.next(); e=self.parse_expr(); items.append(("spreaditem",e))
            elif (self.peek().kind in ("IDENT","STR")) and self.peek_nl_skip(1).kind==":":
                is_dict=True
                keytok=self.next(); key=keytok.val; self.skip_nl(); self.expect(":")
                val=self.parse_expr(); items.append(("dictitem",(key,val)))
            else:
                e=self.parse_expr(); items.append(("item",e))
            self.skip_nl()
            if self.eat(","):
                self.skip_nl()
                if self.peek().kind==")": break
                continue
            break
        close=self.expect(")")
        end=self.base+close.end
        # closure check
        if self.peek().kind=="=>":
            self.next()
            params=[]
            for kind,it in items:
                if kind=="spreaditem":
                    # it is expr node, should be ident
                    if it[0]=="ident": params.append((it[2],None,"sink"))
                    else: raise TypError("expected identifier", it[1])
                elif kind=="dictitem":
                    k,v=it; params.append((k,v,"named"))
                elif kind=="item":
                    e=it
                    if e[0]=="ident": params.append((e[2],None,"pos"))
                    elif e[0]=="lit" and e[2] is None: params.append(("_",None,"pos"))
                    else: raise TypError("expected identifier", e[1])
                else: raise TypError("expected identifier", (start,end))
            body=self.parse_expr_or_block()
            return ("closure",(start,body[1][1]),params,body)
        if is_dict:
            ditems=[]
            for kind,it in items:
                if kind=="dictitem": ditems.append(it)
                elif kind=="spreaditem": ditems.append(("__spread__",it))
                else: raise TypError("expected named pair", (start,end))
            return ("dict",(start,end),ditems)
        # array or grouping
        if len(items)==1 and items[0][0]=="item":
            # check if comma was present: we don't track; single item without trailing comma is group
            # Determine by source: if there was a comma before ')', tokens include ',' before close
            prev2 = self.toks[self.pos-2] if self.pos>=2 else None
            if prev2 is not None and prev2.kind==",":
                return ("array",(start,end),items)
            return items[0][1]
        return ("array",(start,end),items)
    def parse_if(self):
        start=self.next()
        cond=self.parse_expr()
        self.skip_nl(); t=self.peek()
        if t.kind not in ("{","CONTENT"):
            raise TypError("expected block", (self.base+t.start,self.base+t.end))
        body=self.parse_expr_or_block() if t.kind=="{" else self.parse_postfix_body()
        else_branch=None
        # else may be on next line
        save=self.pos
        self.skip_nl()
        if self.peek().kind=="IDENT" and self.peek().val=="else":
            self.next(); self.skip_nl()
            if self.peek().kind=="IDENT" and self.peek().val=="if": else_branch=self.parse_if()
            else:
                tt=self.peek()
                if tt.kind not in ("{","CONTENT"): raise TypError("expected block", (self.base+tt.start,self.base+tt.end))
                else_branch=self.parse_expr_or_block() if tt.kind=="{" else self.parse_postfix_body()
        else:
            self.pos=save
        return ("if",(self.base+start.start,(else_branch or body)[1][1]),cond,body,else_branch)
    def parse_postfix_body(self):
        t=self.next()  # CONTENT
        return ("content",(self.base+t.start,self.base+t.end),t.val[0],t.val[1])
    def parse_for(self):
        start=self.next()
        pattern=self.parse_pattern()
        self.skip_nl()
        t=self.peek()
        if not (t.kind=="IDENT" and t.val=="in"): raise TypError("expected `in`", (self.base+t.start,self.base+t.end))
        self.next()
        iterexpr=self.parse_expr()
        self.skip_nl(); tt=self.peek()
        if tt.kind not in ("{","CONTENT"): raise TypError("expected block", (self.base+tt.start,self.base+tt.end))
        body=self.parse_expr_or_block() if tt.kind=="{" else self.parse_postfix_body()
        return ("for",(self.base+start.start,body[1][1]),pattern,iterexpr,body)
    def parse_while(self):
        start=self.next()
        cond=self.parse_expr()
        self.skip_nl(); tt=self.peek()
        if tt.kind not in ("{","CONTENT"): raise TypError("expected block", (self.base+tt.start,self.base+tt.end))
        body=self.parse_expr_or_block() if tt.kind=="{" else self.parse_postfix_body()
        return ("while",(self.base+start.start,body[1][1]),cond,body)

def parse_code(src, base=0):
    p=Parser(src, base)
    return p.parse_top()
