class Tok:
    __slots__=("kind","val","start","end")
    def __init__(self,kind,val,start,end): self.kind=kind; self.val=val; self.start=start; self.end=end
    def __repr__(self): return f"Tok({self.kind},{self.val!r})"

def _is_ident_start(c): return c.isalpha() or c=="_"
def _is_ident_char(c): return c.isalnum() or c=="_"

class Lexer:
    def __init__(self, src, base=0):
        self.s=src; self.i=0; self.base=base; self.toks=[]
    def err(self,msg,pos=None):
        p=self.i if pos is None else pos
        raise TypError(msg, (self.base+p, self.base+p+1))
    def tokenize(self):
        s=self.s; n=len(s)
        while self.i<n:
            c=s[self.i]; start=self.i
            if c in " \t\r": self.i+=1; continue
            if c=="\n": self.toks.append(Tok("NL",None,start,start+1)); self.i+=1; continue
            if s.startswith("//", self.i):
                while self.i<n and s[self.i]!="\n": self.i+=1
                continue
            if s.startswith("/*", self.i):
                depth=1; self.i+=2
                while self.i<n and depth:
                    if s.startswith("/*",self.i): depth+=1; self.i+=2
                    elif s.startswith("*/",self.i): depth-=1; self.i+=2
                    else: self.i+=1
                if depth: self.err("unclosed comment", start)
                continue
            if c=='"':
                self.lex_string(); continue
            if c=='`':
                self.lex_raw(); continue
            if c=='$':
                # math: capture to next $
                j=self.i+1
                while j<n:
                    if s[j]=="\\" : j+=2; continue
                    if s[j]=="$": break
                    j+=1
                if j>=n: self.err("unclosed math", start)
                raw=s[self.i+1:j]
                self.toks.append(Tok("MATH", raw, start, j+1)); self.i=j+1; continue
            if c=='[':
                raw, end = self.capture_content(self.i)
                self.toks.append(Tok("CONTENT", (raw, self.base+start+1), start, end)); self.i=end; continue
            if c.isdigit() or (c=='.' and self.i+1<n and s[self.i+1].isdigit()):
                self.lex_number(); continue
            if _is_ident_start(c):
                j=self.i+1
                while j<n:
                    if _is_ident_char(s[j]): j+=1
                    elif s[j]=='-' and j+1<n and (_is_ident_char(s[j+1])) and s[j-1]!='-': j+=1
                    else: break
                word=s[self.i:j]
                self.toks.append(Tok("IDENT", word, start, j)); self.i=j; continue
            # operators / punctuation
            two=s[self.i:self.i+2]
            if two in ("==","!=","<=",">=","=>","..","+=","-=","*=","/="):
                self.toks.append(Tok(two,two,start,start+2)); self.i+=2; continue
            if c in "+-*/=<>(),;:{}." :
                self.toks.append(Tok(c,c,start,start+1)); self.i+=1; continue
            if c=='#':
                self.toks.append(Tok("#",c,start,start+1)); self.i+=1; continue
            if c=='\'':
                self.err("the character `'` is not valid in code", start)
            if c=='%':
                self.err("the character `%` is not valid in code", start)
            self.err(f"the character `{c}` is not valid in code", start)
        self.toks.append(Tok("EOF",None,n,n))
        return self.toks
    def lex_string(self):
        s=self.s; n=len(s); start=self.i; self.i+=1; out=[]
        while self.i<n:
            c=s[self.i]
            if c=='"':
                self.i+=1; self.toks.append(Tok("STR", "".join(out), start, self.i)); return
            if c=='\n': self.err("unclosed string", start)
            if c=='\\':
                self.i+=1
                if self.i>=n: break
                e=s[self.i]
                mp={'n':'\n','r':'\r','t':'\t','\\':'\\','"':'"',"'":"'",'e':'\x1b'}
                if e in mp: out.append(mp[e]); self.i+=1
                elif e=='u':
                    self.i+=1
                    if self.i<n and s[self.i]=='{':
                        j=s.find('}',self.i)
                        if j<0: self.err("unclosed Unicode escape", start)
                        hexs=s[self.i+1:j]
                        try: out.append(chr(int(hexs,16)))
                        except Exception: self.err("invalid Unicode escape", start)
                        self.i=j+1
                    else: self.err("expected `{` in Unicode escape", start)
                else:
                    self.err(f"invalid escape sequence: \\{e}", self.i-1)
                continue
            out.append(c); self.i+=1
        self.err("unclosed string", start)
    def lex_raw(self):
        s=self.s; n=len(s); start=self.i
        cnt=0
        while self.i<n and s[self.i]=='`': cnt+=1; self.i+=1
        if cnt>=3:
            # optional lang ident
            lang=None; ls=self.i
            while self.i<n and (_is_ident_char(s[self.i]) or s[self.i]=='-'): self.i+=1
            if self.i>ls: lang=s[ls:self.i]
            # content until ```...
            fence='`'*cnt
            j=s.find(fence, self.i)
            if j<0: self.err("unclosed raw", start)
            raw=s[self.i:j]
            # strip leading/trailing newline like block raw
            if raw.startswith("\n"): raw=raw[1:]
            if raw.endswith("\n"): raw=raw[:-1]
            self.toks.append(Tok("RAW", (raw, True, lang), start, j+cnt)); self.i=j+cnt; return
        else:
            j=s.find('`', self.i)
            if j<0: self.err("unclosed raw", start)
            raw=s[self.i:j]
            self.toks.append(Tok("RAW", (raw, False, None), start, j+1)); self.i=j+1; return
    def capture_content(self, i):
        s=self.s; n=len(s); depth=0; j=i
        while j<n:
            c=s[j]
            if c=='\\': j+=2; continue
            if c=='"':
                j+=1
                while j<n and s[j]!='"':
                    if s[j]=='\\': j+=1
                    j+=1
                j+=1; continue
            if c=='[': depth+=1
            elif c==']':
                depth-=1
                if depth==0: return s[i+1:j], j+1
            j+=1
        raise TypError("unclosed content block", (self.base+i, self.base+i+1))
    def lex_number(self):
        s=self.s; n=len(s); start=self.i
        # radix
        if s.startswith(("0x","0X","0o","0O","0b","0B"), self.i):
            kind=s[self.i+1].lower(); base={'x':16,'o':8,'b':2}[kind]
            j=self.i+2
            while j<n and (s[j].isalnum() or s[j]=='_'): j+=1
            txt=s[self.i+2:j].replace("_","")
            try: val=int(txt, base)
            except Exception: self.err("invalid number", start)
            self.toks.append(Tok("NUM", val, start, j)); self.i=j; return
        j=self.i
        while j<n and (s[j].isdigit() or s[j]=='_'): j+=1
        is_float=False
        if j<n and s[j]=='.' and j+1<n and s[j+1].isdigit():
            is_float=True; j+=1
            while j<n and (s[j].isdigit() or s[j]=='_'): j+=1
        if j<n and s[j] in 'eE':
            k=j+1
            if k<n and s[k] in '+-': k+=1
            if k<n and s[k].isdigit():
                is_float=True; j=k
                while j<n and (s[j].isdigit() or s[j]=='_'): j+=1
        txt=s[self.i:j].replace("_","")
        # suffix
        suffix=None
        if j<n and s[j]=='%': suffix="%"; j+=1
            # invalid suffix like %2 handled by parser? If digit follows immediately, typst errors "invalid number suffix: %2"
        elif j<n and s[j].isalpha():
            k=j
            while k<n and s[k].isalpha(): k+=1
            suffix=s[j:k]; j=k
        if suffix is not None:
            if suffix not in UNITS:
                # include following digit? e.g. %2 case: suffix token is % and next digit starts number, but typst reported "%2"
                self.err(f"invalid number suffix: {suffix}", start)
            val=float(txt) if is_float or True else int(txt)
            v=UNITS[suffix](float(txt))
            self.toks.append(Tok("NUM", v, start, j)); self.i=j; return
        val=float(txt) if is_float else int(txt)
        # very large int -> typst falls back to float
        if isinstance(val,int) and abs(val) >= 2**63:
            val=float(val)
        self.toks.append(Tok("NUM", val, start, j)); self.i=j

# ---------------- Parser ----------------
# AST nodes are tuples: (kind, span, ...)
class Parser:
    def __init__(self, src, base=0):
        self.src=src; self.base=base
        self.toks=Lexer(src, base).tokenize()
        self.pos=0
    # token helpers
    def peek(self, k=0):
        idx=min(self.pos+k, len(self.toks)-1)
        # expose non-NL lookahead helper separately
        return self.toks[idx]
    def peek_nl_skip(self, k=0):
        cnt=-1; i=self.pos
        while i < len(self.toks):
            t=self.toks[i]
            if t.kind=="NL": i+=1; continue
            cnt+=1
            if cnt==k: return t
            i+=1
        return self.toks[-1]
    def next(self):
        t=self.toks[self.pos]; self.pos+=1; return t
    def skip_nl(self):
        while self.pos<len(self.toks) and self.toks[self.pos].kind=="NL": self.pos+=1
    def at(self, kind):
        self.skip_nl(); return self.peek().kind==kind
    def eat(self, kind):
        self.skip_nl()
        if self.peek().kind==kind: return self.next()
        return None
    def expect(self, kind, msg=None):
        self.skip_nl(); t=self.peek()
        if t.kind!=kind:
            raise TypError(msg or f"expected {kind}", (self.base+t.start, self.base+t.end))
        return self.next()
    def span(self,a,b): return (self.base+a, self.base+b)

    def parse_top(self):
        stmts=self.parse_statements(end="EOF")
        return ("block", (self.base, self.base+len(self.src)), stmts, True)

    def parse_statements(self, end="EOF"):
        stmts=[]
        while True:
            # skip separators
            while self.peek().kind in ("NL",";"): self.next()
            if self.peek().kind==end or self.peek().kind=="EOF": break
            if end=="}" and self.peek().kind=="}": break
            stmt_start=self.peek()
            stmt=self.parse_statement()
            stmts.append(stmt)
            # separator check
            t=self.peek()
            if t.kind in ("NL",";","EOF","}"): continue
            # next token on later line than stmt end?
            # Our NL tokens cover this; if no NL/semicolon, error
            raise TypError("expected semicolon or line break", (self.base+t.start, self.base+t.end))
        return stmts

    def parse_statement(self):
        self.skip_nl(); t=self.peek()
        if t.kind=="IDENT":
            w=t.val
            if w=="let": return self.parse_let()
            if w=="set": return self.parse_set()
            if w=="show": return self.parse_show()
            if w=="import": return self.parse_import(False)
            if w=="include": return self.parse_import(True)
            if w=="return":
                self.next()
                if self.peek().kind in ("NL",";","}","EOF"): return ("return",(self.base+t.start,self.base+t.end),None)
                expr=self.parse_expr()
                return ("return",(self.base+t.start,self.base+expr[1][1]),expr)
            if w=="break": self.next(); return ("break",(self.base+t.start,self.base+t.end))
            if w=="continue": self.next(); return ("continue",(self.base+t.start,self.base+t.end))
        expr=self.parse_expr()
        # assignment?
        self.skip_nl(); t2=self.peek()
        if t2.kind in ("=","+=","-=","*=","/="):
            op=self.next().kind
            val=self.parse_expr()
            return ("assign", (expr[1][0], val[1][1]), expr, op, val)
        return expr

    def parse_let(self):
        start=self.next()  # let
        self.skip_nl()
        # function definition: IDENT '(' params ')' '='
        save=self.pos
        if self.peek().kind=="IDENT" and self.peek_nl_skip(1).kind=="(":
            name=self.next().val
            params=self.parse_params_paren()
            self.skip_nl()
            if self.peek().kind=="=":
                self.next(); body=self.parse_expr_or_block()
                return ("letfunc", (self.base+start.start, body[1][1]), name, params, body)
            else:
                raise TypError("expected equals sign", (self.base+self.peek().start, self.base+self.peek().end))
        pattern=self.parse_pattern()
        self.skip_nl()
        if self.peek().kind!="=":
            t=self.peek(); raise TypError("expected equals sign", (self.base+t.start,self.base+t.end))
        self.next()
        value=self.parse_expr()
        return ("let", (self.base+start.start, value[1][1]), pattern, value)

    def parse_pattern(self):
        self.skip_nl(); t=self.peek()
        if t.kind=="..":
            self.next(); nt=self.expect("IDENT","expected identifier")
            return ("sinkpat", (self.base+t.start,self.base+nt.end), nt.val)
        if t.kind=="(":
            self.next()
            items=[]
            self.skip_nl()
            if self.eat(")"): return ("tuppat",(self.base+t.start,self.base+t.end),items)
            while True:
                self.skip_nl()
                if self.peek().kind=="..":
                    items.append(self.parse_pattern())
                elif self.peek().kind=="IDENT" and self.peek_nl_skip(1).kind==":":
                    key=self.next().val; self.next()  # colon (skip_nl inside? colon token direct)
                    # note peek_nl_skip consumed nothing; need eat colon properly
                    pat=self.parse_pattern()
                    items.append(("keypat", pat[1], key, pat))
                else:
                    items.append(self.parse_pattern())
                self.skip_nl()
                if self.eat(","): 
                    self.skip_nl()
                    if self.peek().kind==")": break
                    continue
                break
            self.expect(")")
            return ("tuppat",(self.base+t.start,self.base+self.toks[self.pos-1].end),items)
        if t.kind=="IDENT":
            self.next(); return ("identpat",(self.base+t.start,self.base+t.end),t.val)
        raise TypError("expected pattern", (self.base+t.start,self.base+t.end))

    def parse_params_paren(self):
        # expects current '(' (without skipping? skip nl ok)
        open_tok=self.expect("(")
        params=[]  # (name, default_node or None, kind: pos/named/sink)
        self.skip_nl()
        if self.eat(")"): return params
        while True:
            self.skip_nl()
            if self.peek().kind=="..":
                st=self.next(); name_tok=self.expect("IDENT","expected identifier")
                params.append((name_tok.val, None, "sink"))
            elif self.peek().kind=="IDENT":
                # could be named default: IDENT ':' expr  or just ident or ident =? typst uses colon for named in defs
                name_tok=self.next(); name=name_tok.val
                self.skip_nl()
                if self.peek().kind==":":
                    self.next(); default=self.parse_expr()
                    params.append((name, default, "named"))
                else:
                    params.append((name, None, "pos"))
            elif self.peek().kind=="_":
                self.next(); params.append(("_",None,"pos"))
            else:
                # unnamed placeholder token '_' is ident? '_' lexed as ident starting _
                t=self.peek(); raise TypError("expected identifier", (self.base+t.start,self.base+t.end))
            self.skip_nl()
            if self.eat(","):
                self.skip_nl()
                if self.peek().kind==")": break
                continue
            break
        self.expect(")")
        return params

    def parse_set(self):
        start=self.next()
        self.skip_nl()
        name_tok=self.expect("IDENT","expected identifier")
        # dotted target e.g. set text.font? typst set targets are element funcs (possibly module member)
        target=("ident",(self.base+name_tok.start,self.base+name_tok.end),name_tok.val)
        while self.peek().kind==".":
            self.next(); nt=self.expect("IDENT"); target=("field",(target[1][0],self.base+nt.end),target,nt.val)
        args=self.parse_call_args_and_content()
        node=("set",(self.base+start.start, self.toks[self.pos-1].end if self.pos else self.base+start.end), target, args)
        return node

    def parse_show(self):
        start=self.next()
        # parse selector expr until ':' at depth 0 - simple: parse expr, but colon isn't operator except dict/args, parse primary-ish
        # We parse an expression that stops before ':' - our parse_expr doesn't consume ':' so fine
        sel=self.parse_expr()
        self.skip_nl()
        if self.peek().kind!=":":
            t=self.peek(); raise TypError("expected colon", (self.base+t.start,self.base+t.end))
        self.next()
        transform=self.parse_expr_or_block()
        return ("show",(self.base+start.start, transform[1][1]), sel, transform)

    def parse_import(self, include):
        start=self.next()
        if include:
            expr=self.parse_expr()
            return ("include",(self.base+start.start,expr[1][1]),expr)
        expr=self.parse_expr()
        items=None; alias=None
        self.skip_nl()
        if self.peek().kind=="IDENT" and self.peek().val=="as":
            self.next(); alias=self.expect("IDENT").val
        elif self.peek().kind==":":
            self.next(); items=[]
            # items: ident, ident as alias, *
            while True:
                self.skip_nl()
                if self.peek().kind=="*": self.next(); items.append("*")
                else:
                    nm=self.expect("IDENT").val
                    al=None
                    if self.peek().kind=="IDENT" and self.peek().val=="as": self.next(); al=self.expect("IDENT").val
                    items.append((nm,al))
                self.skip_nl()
                if self.eat(","): continue
                break
        return ("import",(self.base+start.start,self.toks[self.pos-1].end),expr,items,alias)

    def parse_expr_or_block(self):
        self.skip_nl(); t=self.peek()
        if t.kind=="{":
            return self.parse_codeblock()
        return self.parse_expr()

    def parse_codeblock(self):
        open_tok=self.expect("{")
        stmts=self.parse_statements(end="}")
        close=self.expect("}")
        return ("block",(self.base+open_tok.start,self.base+close.end),stmts,False)

    # expression grammar
    def parse_expr(self):
        return self.parse_assign_expr()
    def parse_assign_expr(self):
        # closure detection handled in primary; just parse or-level
        return self.parse_or()
    def parse_or(self):
        left=self.parse_and()
        while True:
            self.skip_nl_save=None
            # 'or' keyword; but don't consume across newline for statement-level? inside expr allowed
            t=self.peek_nl_skip(0)
            if t.kind=="IDENT" and t.val=="or":
                # consume (with NLs)
                self.skip_nl(); self.next(); right=self.parse_and(); left=("bin",(left[1][0],right[1][1]),"or",left,right)
            else: break
        return left
    def parse_and(self):
        left=self.parse_compare()
        while True:
            t=self.peek_nl_skip(0)
            if t.kind=="IDENT" and t.val=="and":
                self.skip_nl(); self.next(); right=self.parse_compare(); left=("bin",(left[1][0],right[1][1]),"and",left,right)
            else: break
        return left
    def parse_compare(self):
        left=self.parse_add()
        while True:
            t=self.peek_nl_skip(0)
            op=None
            if t.kind in ("==","!=","<","<=",">",">="): op=t.kind
            elif t.kind=="IDENT" and t.val=="in": op="in"
            elif t.kind=="IDENT" and t.val=="not" and self.peek_nl_skip(1).kind=="IDENT" and self.peek_nl_skip(1).val=="in": op="not in"
            if not op: break
            self.skip_nl(); self.next()
            if op=="not in": self.skip_nl(); self.next()
            right=self.parse_add(); left=("bin",(left[1][0],right[1][1]),op,left,right)
        return left
    def parse_add(self):
        left=self.parse_mul()
        while True:
            t=self.peek()  # do not skip NL: binary across lines in parens handled elsewhere? skip spaces only (tokens have no spaces)
            # If next is + or - on same 'logical' position; NL tokens would appear - in args, lines can break before op rarely
            if t.kind in ("+","-"):
                # peek raw token without skipping NL: if NL before op, typst still allows in expressions inside brackets; treat as op if token is +/- 
                op=self.next().kind; right=self.parse_mul(); left=("bin",(left[1][0],right[1][1]),op,left,right)
            else: break
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while True:
            t=self.peek()
            if t.kind in ("*","/"):
                op=self.next().kind; right=self.parse_unary(); left=("bin",(left[1][0],right[1][1]),op,left,right)
            else: break
        return left
    def parse_unary(self):
        self.skip_nl(); t=self.peek()
        if t.kind in ("-","+"):
            self.next(); operand=self.parse_unary(); return ("un",(self.base+t.start,operand[1][1]),t.kind,operand)
        if t.kind=="IDENT" and t.val=="not":
            self.next(); operand=self.parse_unary(); return ("un",(self.base+t.start,operand[1][1]),"not",operand)
        return self.parse_postfix()
    def parse_postfix(self):
        expr=self.parse_primary()
        while True:
            t=self.peek()
            if t.kind==".":
                self.next()
                # method/field could be number? e.g. (1,2).0? no
                nt=self.peek()
                if nt.kind!="IDENT": raise TypError("expected identifier", (self.base+nt.start,self.base+nt.end))
                self.next(); expr=("field",(expr[1][0],self.base+nt.end),expr,nt.val)
                continue
            if t.kind=="(":
                args=self.parse_call_args_and_content(already_open=True)
                expr=("call",(expr[1][0],args[2]),expr,args)
                continue
            if t.kind=="CONTENT":
                ct=self.next(); content_node=("content",(self.base+ct.start,self.base+ct.end),ct.val[0],ct.val[1])
                # content block as trailing arg to a call/expression: if expr is ident/call/field => add to args
                if expr[0] in ("ident","field"):
                    expr=("call",(expr[1][0],content_node[1][1]),expr, ([],{},[content_node], content_node[1][1]))
                elif expr[0]=="call":
                    expr[3][2].append(content_node)
                else:
                    # applying content to non-function handled at eval
                    expr=("call",(expr[1][0],content_node[1][1]),expr, ([],{},[content_node], content_node[1][1]))
                continue
            break
        return expr
    def parse_call_args_and_content(self, already_open=False):
        # returns (pos, named, contents, end_offset_base)
        # current token expected '('
        open_tok=self.expect("(")
        pos=[]; named={}
        self.skip_nl()
        if not self.eat(")"):
            while True:
                self.skip_nl()
                if self.peek().kind=="..":
                    st=self.next(); e=self.parse_expr(); pos.append(("spread",e))
                elif self.peek().kind=="IDENT" and self.peek_nl_skip(1).kind==":":
                    name=self.next().val; self.skip_nl(); self.expect(":")
                    val=self.parse_expr(); named[name]=val
                elif self.peek().kind=="STR" and self.peek_nl_skip(1).kind==":":
                    name=self.next().val; self.skip_nl(); self.expect(":")
                    val=self.parse_expr(); named[name]=val
                else:
                    pos.append(self.parse_expr())
                self.skip_nl()
                if self.eat(","):
                    self.skip_nl()
                    if self.peek().kind==")": break
                    continue
                break
            self.expect(")")
        end=self.base+self.toks[self.pos-1].end
        contents=[]
        while self.peek().kind=="CONTENT":
            ct=self.next(); contents.append(("content",(self.base+ct.start,self.base+ct.end),ct.val[0],ct.val[1]))
            end=self.base+ct.end
        return (pos,named,contents,end)
    def parse_primary(self):
        self.skip_nl(); t=self.peek()
        if t.kind=="NUM": self.next(); return ("lit",(self.base+t.start,self.base+t.end),t.val)
        if t.kind=="STR": self.next(); return ("lit",(self.base+t.start,self.base+t.end),t.val)
        if t.kind=="RAW":
            self.next(); raw,block,lang=t.val
            fields={"text":raw}
            if block: fields["block"]=True
            else: fields["block"]=False
            if lang: fields["lang"]=lang
            if not block and "block" in fields:
                pass
            return ("rawcontent",(self.base+t.start,self.base+t.end),fields)
        if t.kind=="MATH":
            self.next(); return ("math",(self.base+t.start,self.base+t.end),t.val)
        if t.kind=="CONTENT":
            self.next(); return ("content",(self.base+t.start,self.base+t.end),t.val[0],t.val[1])
        if t.kind=="{":
            return self.parse_codeblock()
        if t.kind=="(":
            return self.parse_paren_or_closure()
        if t.kind=="<":
            # label
            self.next()
            nt=self.peek()
            if nt.kind=="IDENT":
                self.next()
                gt=self.peek()
                if gt.kind==">": self.next(); return ("lit",(self.base+t.start,self.base+gt.end),Label(nt.val))
                raise TypError("unclosed label", (self.base+t.start,self.base+nt.end))
            raise TypError("unclosed label", (self.base+t.start,self.base+t.end))
        if t.kind=="IDENT":
            w=t.val
            if w=="true": self.next(); return ("lit",(self.base+t.start,self.base+t.end),True)
            if w=="false": self.next(); return ("lit",(self.base+t.start,self.base+t.end),False)
            if w=="none": self.next(); return ("lit",(self.base+t.start,self.base+t.end),None)
            if w=="auto": self.next(); return ("lit",(self.base+t.start,self.base+t.end),AUTO)
            if w=="if": return self.parse_if()
            if w=="for": return self.parse_for()
            if w=="while": return self.parse_while()
            if w=="context":
                self.next(); body=self.parse_expr_or_block(); return ("context",(self.base+t.start,body[1][1]),body)
            if w in ("let","set","show"):
                raise TypError(f"unexpected keyword `{w}`", (self.base+t.start,self.base+t.end))
            if w in ("break",):
                # handled in statement; here expression context
                self.next(); return ("break",(self.base+t.start,self.base+t.end))
            if w in ("continue",):
                self.next(); return ("continue",(self.base+t.start,self.base+t.end))
            if w in ("return",):
                self.next(); e=self.parse_expr(); return ("return",(self.base+t.start,e[1][1]),e)
            if w=="else":
                raise TypError("unexpected keyword `else`", (self.base+t.start,self.base+t.end))
            # identifier possibly closure x => ...
            self.next()
            if self.peek().kind=="=>":
                self.next(); body=self.parse_expr_or_block()
                return ("closure",(self.base+t.start,body[1][1]),[(w,None,"pos")],body)
            return ("ident",(self.base+t.start,self.base+t.end),w)
        if t.kind=="}":
            raise TypError("unexpected closing brace", (self.base+t.start,self.base+t.end))
        if t.kind=="EOF":
            raise TypError("expected expression", (self.base+t.start,self.base+t.end))
        if t.kind==",":
            raise TypError("unexpected comma", (self.base+t.start,self.base+t.end))
        if t.kind=="=":
            raise TypError("unexpected equals sign", (self.base+t.start,self.base+t.end))
        if t.kind=="*":
            raise TypError("unexpected star", (self.base+t.start,self.base+t.end))
        if t.kind==":":
            raise TypError("unexpected colon", (self.base+t.start,self.base+t.end))
        if t.kind=="#":
            raise TypError("the character `#` is not valid in code", (self.base+t.start,self.base+t.end), hints=["you are already in code mode","try removing the `#`"])
        raise TypError("expected expression", (self.base+t.start,self.base+t.end))
    def parse_paren_or_closure(self):
        open_tok=self.expect("(")
        start=self.base+open_tok.start
        self.skip_nl()
        if self.peek().kind==")":
            cp=self.next()
            node=("lit",(start,self.base+cp.end),[])
            # closure () => ?
