    def peek(self, k=0):
        idx=min(self.pos+k, len(self.toks)-1)
        # expose non-NL lookahead helper separately
        return self.toks[idx]
    def peek_nl_skip(self, k=0):
        cnt=-1; i=self.pos
        while i < len(self.toks):
            t=self.toks[i]
            if t.kind=="NL": i+=1; continue
            cnt+=1
            if cnt==k: return t
            i+=1
        return self.toks[-1]
    def next(self):
        t=self.toks[self.pos]; self.pos+=1; return t
    def skip_nl(self):
        while self.pos<len(self.toks) and self.toks[self.pos].kind=="NL": self.pos+=1
    def at(self, kind):
        self.skip_nl(); return self.peek().kind==kind
    def eat(self, kind):
        self.skip_nl()
        if self.peek().kind==kind: return self.next()
        return None
    def expect(self, kind, msg=None):
        self.skip_nl(); t=self.peek()
        if t.kind!=kind:
            raise TypError(msg or f"expected {kind}", (self.base+t.start, self.base+t.end))
        return self.next()
    def span(self,a,b): return (self.base+a, self.base+b)

    def parse_top(self):
        stmts=self.parse_statements(end="EOF")
        return ("block", (self.base, self.base+len(self.src)), stmts, True)

    def parse_statements(self, end="EOF"):
        stmts=[]
        while True:
            # skip separators
            while self.peek().kind in ("NL",";"): self.next()
            if self.peek().kind==end or self.peek().kind=="EOF": break
            if end=="}" and self.peek().kind=="}": break
            stmt_start=self.peek()
            stmt=self.parse_statement()
            stmts.append(stmt)
            # separator check
            t=self.peek()
            if t.kind in ("NL",";","EOF","}"): continue
            # next token on later line than stmt end?
            # Our NL tokens cover this; if no NL/semicolon, error
            raise TypError("expected semicolon or line break", (self.base+t.start, self.base+t.end))
