# ---------- type constructors ----------
def call_type_constructor(ev, t, args, span=None):
    name=t.name
    if name=="bool": raise TypError("type boolean does not have a constructor", span)
    if name=="int":
        if not args.pos: raise TypError("missing argument: value", span)
        v=args.pos[0]
        return to_int(v,args,span)
    if name=="float":
        if not args.pos: raise TypError("missing argument: value", span)
        v=args.pos[0]
        if is_num(v): return float(v)
        if isinstance(v,str):
            try: return float(v)
            except Exception: raise TypError("string contains invalid digits", span)
        if isinstance(v,DecimalVal): return float(v.s)
        if isinstance(v,bool): return 1.0 if v else 0.0
        raise TypError(f"expected integer, float, decimal, or string, found {dtype(v)}", span)
    if name=="str":
        if not args.pos: raise TypError("missing argument: value", span)
        if len(args.pos)>1: raise TypError("unexpected argument", span)
        v=args.pos[0]
        if isinstance(v,str): return str(v)
        if is_int(v): return str(v)
        if isinstance(v,float): return fmt_float_str(v)
        if isinstance(v,DecimalVal): return v.s
        if isinstance(v,VersionVal): return ".".join(str(x) for x in v.parts)
        if isinstance(v,BytesVal):
            try: return v.data.decode("utf-8")
            except Exception: raise TypError("bytes are not valid utf-8", span)
        if isinstance(v,Label): return v.name
        if isinstance(v,TypeVal): return repr_val(v)
        raise TypError(f"expected integer, float, decimal, version, bytes, label, type, or string, found {dtype(v)}", span)
    if name=="array":
        if not args.pos: return []
        v=args.pos[0]
        if isinstance(v,list): return list(v)
        if isinstance(v,ArgumentsVal): return v.pos
        if isinstance(v,BytesVal): return list(v.data)
        if isinstance(v,dict): return [[k,val] for k,val in v.items()]
        raise TypError(f"expected array, arguments, bytes, or dictionary, found {dtype(v)}", span)
    if name=="bytes":
        if not args.pos: return BytesVal(b"")
        v=args.pos[0]
        if isinstance(v,str): return BytesVal(v.encode())
        if isinstance(v,list): return BytesVal(bytes(int(x)%256 for x in v))
        if isinstance(v,BytesVal): return v
        raise TypError(f"expected string, array, or bytes, found {dtype(v)}", span)
    if name=="decimal":
        if not args.pos: raise TypError("missing argument: value", span)
        v=args.pos[0]
        if isinstance(v,DecimalVal): return v
        if is_int(v): return DecimalVal(str(v))
        if isinstance(v,float): return DecimalVal(fmt_float_str(v))
        if isinstance(v,str):
            # validate
            try:
                from decimal import Decimal; Decimal(v)
            except Exception: raise TypError("string contains invalid decimal", span)
            return DecimalVal(v)
        raise TypError(f"expected integer, float, or string, found {dtype(v)}", span)
    if name=="datetime":
        # datetime(...) construction or datetime.today field handled in get_field
        y=args.named.get("year"); mo=args.named.get("month"); d=args.named.get("day")
        h=args.named.get("hour"); mi=args.named.get("minute"); sec=args.named.get("second")
        if y is None and h is None: raise TypError("at least one of date or time must be fully specified", span)
        return DatetimeVal(y,mo,d,h,mi,sec)
    if name=="duration":
        weeks=args.named.get("weeks",0) or 0; days=args.named.get("days",0) or 0; hours=args.named.get("hours",0) or 0; minutes=args.named.get("minutes",0) or 0; seconds=args.named.get("seconds",0) or 0
        return DurationVal(weeks*7*86400+days*86400+hours*3600+minutes*60+seconds)
    if name=="version":
        parts=[]
        for v in args.pos:
