        run=None; run_style=None; run_x=None
        def flush_run():
            if run: self.add_op(("text",run_x,baseline,run,run_style))
        for tok in line:
            if tok.kind=="space": 
                if run is not None: run+=" "; cx+=tok.width(); continue
                cx+=tok.width(); continue
            if tok.kind=="atomic":
                flush_run(); run=None
                if tok.content is not None and isinstance(tok.content,Content) and tok.content.func=="image":
                    path=resolve_image_path(tok.content.fields.get("source",""), self.root_dir, self.doc)
                    self.add_op(("image",cx,baseline-tok.style.get("size",11),tok.style.get("_w",50),tok.style.get("size",11),path or ""))
                cx+=tok.width(); continue
            if run_style is not None and tok.style==run_style:
                run+=tok.text
            else:
                flush_run(); run=tok.text; run_style=dict(tok.style); run_x=cx
            cx+=tok.width()
