def format_numbering(pattern, counters):
    # pattern like "1." "1.1" "A.a" etc
    out=""; ci=0
    for ch in pattern:
        if ch in "1aAiI" and ci < len(counters)+5:
            val=counters[ci] if ci < len(counters) else 1; ci+=1
            if ch=="1": out+=str(val)
            elif ch=="a": out+=chr(ord('a')+(val-1)%26)
            elif ch=="A": out+=chr(ord('A')+(val-1)%26)
            elif ch in "iI":
                r=to_roman(val); out+= r if ch=="I" else r.lower()
            else: out+=str(val)
        else: out+=ch
    return out
def to_roman(n):
    vals=[(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),(50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]
    out=""
    for v,s in vals:
        while n>=v: out+=s; n-=v
    return out
def resolve_image_path(src,root_dir,doc):
    if not src or not isinstance(src,str): return None
    if src.startswith("/"):
        root=getattr(doc,"root_abs",None) or root_dir
        p=os.path.join(root,src.lstrip("/"))
    else:
        main=getattr(doc,"main_path",None)
        base=os.path.dirname(main) if main else root_dir
        p=os.path.join(base,src)
    return p if os.path.isfile(p) else None
def image_size(src, root_dir, doc):
    p=resolve_image_path(src,root_dir,doc)
    if not p: return (None,None)
    try:
        with open(p,"rb") as f: data=f.read(65536)
        if data[:8]==b"\x89PNG\r\n\x1a\n":
            w,h=struct.unpack(">II", data[16:24]); return (float(w),float(h))
        if data[:2]==b"\xff\xd8":
            # jpeg scan
            i=2
            full=open(p,"rb").read()
            while i<len(full)-9:
                if full[i]!=0xff: i+=1; continue
                marker=full[i+1]
                if marker in (0xc0,0xc1,0xc2):
                    h,w=struct.unpack(">HH", full[i+5:i+9]); return (float(w),float(h))
                length=struct.unpack(">H", full[i+2:i+4])[0]; i+=2+length
            return (None,None)
        if data[:6] in (b"GIF87a",b"GIF89a"):
            w,h=struct.unpack("<HH", data[6:10]); return (float(w),float(h))
        if data[:5]==b"<svg " or data[:5]==b"<?xml":
            txt=data.decode("utf-8","ignore")
            m=re.search(r'width="([\d.]+)',txt); n2=re.search(r'height="([\d.]+)',txt)
            if m and n2: return (float(m.group(1)),float(n2.group(1)))
    except Exception: pass
    return (None,None)

