class Tok:
    __slots__=("text","style","kind","content")
    def __init__(self,text,style,kind="word",content=None): self.text=text; self.style=dict(style); self.kind=kind; self.content=content
    def width(self):
        if self.kind=="space": return char_width(" ", self.style)
        if self.kind=="atomic": return self.style.get("_w", 50)
        return sum(char_width(c,self.style) for c in self.text)

def apply_text_settings(style, settings):
    if not isinstance(settings,dict): return style
    st=dict(style)
    if "size" in settings:
        v=resolve_length(settings["size"], st.get("size",11))
        if v: st["size"]=v
    if "font" in settings and isinstance(settings["font"],str): st["font"]=settings["font"]
    if "weight" in settings: st["weight"]=settings["weight"]
    if "style" in settings: st["italic"]= (settings["style"]=="italic")
    if "fill" in settings: st["color"]=color_hex(settings["fill"], st.get("color","#000000"))
    if "tracking" in settings: pass
    return st

def flatten_inline(content, style, tokens):
    if content is None: return
    if isinstance(content,str):
        _append_text(content, style, tokens); return
    if not isinstance(content,Content):
        _append_text(display_val(content), style, tokens); return
    f=content.func; fields=content.fields
    if f=="text": _append_text(str(fields.get("text","")), style, tokens); return
    if f=="strong":
        st=dict(style); st["weight"]=700; flatten_inline(fields.get("body"),st,tokens); return
    if f=="emph":
        st=dict(style); st["italic"]=True; flatten_inline(fields.get("body"),st,tokens); return
    if f=="styled":
        st=apply_text_settings(style, (content.style or {}).get("text",{}) if content.style else {})
        flatten_inline(fields.get("child"),st,tokens); return
    if f=="raw":
        st=dict(style); st["mono"]=True; st["size"]=style.get("size",11)*0.92
        _append_text(str(fields.get("text","")), st, tokens); return
    if f=="sequence":
        for c in fields.get("children",[]): flatten_inline(c,style,tokens)
        return
    if f=="linebreak": tokens.append(Tok("",style,"break")); return
    if f=="h":
        w=resolve_length(fields.get("amount"), style.get("size",11), 0) or 0
        t=Tok("",style,"atomic"); t.style["_w"]=w; tokens.append(t); return
    if f=="label": return
    if f=="metadata" or f=="hide": return
    if f=="link":
        st=dict(style); st["underline"]=True
        flatten_inline(fields.get("body"),st,tokens); return
    if f=="ref":
        tgt=fields.get("target"); name=tgt.name if isinstance(tgt,Label) else str(tgt)
        _append_text(name, style, tokens); return
    if f in ("box","block","par","quote","figure"):
        flatten_inline(fields.get("body"),style,tokens); return
    if f=="equation":
        flatten_inline(fields.get("body"),style,tokens); return
    if f=="attach":
        flatten_inline(fields.get("base"),style,tokens)
        if "t" in fields:
            st=dict(style); st["size"]=style.get("size",11)*0.7; st["sup"]=True; flatten_inline(fields["t"],st,tokens)
        if "b" in fields:
            st=dict(style); st["size"]=style.get("size",11)*0.7; st["sub"]=True; flatten_inline(fields["b"],st,tokens)
        return
    if f=="symbol": _append_text(str(fields.get("text","")),style,tokens); return
    if f=="image":
        t=Tok("[image]",style,"atomic",content); t.style["_w"]=50; tokens.append(t); return
    if "body" in fields:
        flatten_inline(fields.get("body"),style,tokens); return
    if "child" in fields:
        flatten_inline(fields.get("child"),style,tokens); return
    # fallback text_content
    txt=content.text_content()
    if txt: _append_text(txt,style,tokens)

def _append_text(text, style, tokens):
    # split into words and spaces preserving tokens
    parts=re.findall(r"\S+|\s+", text)
    for part in parts:
        if part.isspace(): tokens.append(Tok(" ",style,"space"))
        else: tokens.append(Tok(part,style,"word"))

def wrap_tokens(tokens, width):
    lines=[]; cur=[]; curw=0
    for tok in tokens:
        if tok.kind=="break":
            lines.append(cur); cur=[]; curw=0; continue
        if tok.kind=="space":
            if cur: 
                # tentative, add if next fits later - append as marker
                cur.append(tok); curw+=tok.width()
            continue
        w=tok.width()
        if cur and curw+w>width and width>0:
            # trim trailing spaces
            while cur and cur[-1].kind=="space": cur.pop()
            lines.append(cur); cur=[tok]; curw=w
        else:
            cur.append(tok); curw+=w
    if cur or not lines:
        while cur and cur[-1].kind=="space": cur.pop()
        lines.append(cur)
    return lines

