def format_numbering(pattern, counters):
    # pattern like "1." "1.1" "A.a" etc
    out=""; ci=0
    for ch in pattern:
        if ch in "1aAiI" and ci < len(counters)+5:
            val=counters[ci] if ci < len(counters) else 1; ci+=1
            if ch=="1": out+=str(val)
            elif ch=="a": out+=chr(ord('a')+(val-1)%26)
            elif ch=="A": out+=chr(ord('A')+(val-1)%26)
            elif ch in "iI":
                r=to_roman(val); out+= r if ch=="I" else r.lower()
            else: out+=str(val)
        else: out+=ch
    return out
def to_roman(n):
    vals=[(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),(50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]
    out=""
    for v,s in vals:
        while n>=v: out+=s; n-=v
    return out
def resolve_image_path(src,root_dir,doc):
    if not src or not isinstance(src,str): return None
    if src.startswith("/"):
        root=getattr(doc,"root_abs",None) or root_dir
        p=os.path.join(root,src.lstrip("/"))
    else:
        main=getattr(doc,"main_path",None)
        base=os.path.dirname(main) if main else root_dir
        p=os.path.join(base,src)
