def apply_text_settings(style, settings):
    if not isinstance(settings,dict): return style
    st=dict(style)
    if "size" in settings:
        v=resolve_length(settings["size"], st.get("size",11))
        if v: st["size"]=v
    if "font" in settings and isinstance(settings["font"],str): st["font"]=settings["font"]
    if "weight" in settings: st["weight"]=settings["weight"]
    if "style" in settings: st["italic"]= (settings["style"]=="italic")
    if "fill" in settings: st["color"]=color_hex(settings["fill"], st.get("color","#000000"))
    if "tracking" in settings: pass
    return st

def flatten_inline(content, style, tokens):
    if content is None: return
    if isinstance(content,str):
        _append_text(content, style, tokens); return
    if not isinstance(content,Content):
        _append_text(display_val(content), style, tokens); return
    f=content.func; fields=content.fields
    if f=="text": _append_text(str(fields.get("text","")), style, tokens); return
    if f=="strong":
        st=dict(style); st["weight"]=700; flatten_inline(fields.get("body"),st,tokens); return
    if f=="emph":
        st=dict(style); st["italic"]=True; flatten_inline(fields.get("body"),st,tokens); return
    if f=="styled":
        st=apply_text_settings(style, (content.style or {}).get("text",{}) if content.style else {})
