        return
    if f=="linebreak": tokens.append(Tok("",style,"break")); return
    if f=="h":
        w=resolve_length(fields.get("amount"), style.get("size",11), 0) or 0
        t=Tok("",style,"atomic"); t.style["_w"]=w; tokens.append(t); return
    if f=="label": return
    if f=="metadata" or f=="hide": return
    if f=="link":
        st=dict(style); st["underline"]=True
        flatten_inline(fields.get("body"),st,tokens); return
    if f=="ref":
        tgt=fields.get("target"); name=tgt.name if isinstance(tgt,Label) else str(tgt)
        _append_text(name, style, tokens); return
    if f in ("box","block","par","quote","figure"):
