    def _margins(self, margin):
        default={"left":70.866141732,"right":70.866141732,"top":70.866141732,"bottom":70.866141732}
        if margin is None or margin is AUTO: return default
        if isinstance(margin,dict):
            d=dict(default)
            def get(k, base=None):
                v=margin.get(k)
                if v is None: return None
                return resolve_length(v,11,base)
            if "rest" in margin:
                r=resolve_length(margin["rest"],11,self.page_w)
                if r is not None: d={k:r for k in d}
            if "x" in margin:
                r=resolve_length(margin["x"],11,self.page_w)
                if r is not None: d["left"]=d["right"]=r
            if "y" in margin:
                r=resolve_length(margin["y"],11,self.page_h)
                if r is not None: d["top"]=d["bottom"]=r
            for k,base in (("left",self.page_w),("right",self.page_w),("top",self.page_h),("bottom",self.page_h)):
                if k in margin:
                    r=resolve_length(margin[k],11,base)
                    if r is not None: d[k]=r
            return d
        v=resolve_length(margin,11,self.page_w)
        if v is None: return default
        return {"left":v,"right":v,"top":v,"bottom":v}
