        if content.style and isinstance(content.style,dict) and "text" in content.style:
            st=apply_text_settings(style, content.style["text"])
        handler=getattr(self, "block_"+f, None)
        if handler: handler(content, st, x, width); return
        if f=="par": self._para(fields.get("body"), st,x,width)
        elif f=="sequence":
            inline_buf=[]
            def flush():
                if inline_buf:
                    seq=seq_from(inline_buf); self._para(seq,st,x,width); inline_buf.clear()
            for c in fields.get("children",[]):
                if isinstance(c,Content) and c.func in BLOCK_FUNCS:
                    flush(); self.layout_block(c,st,x,width)
                else: inline_buf.append(c)
            flush()
        elif f in ("text","strong","emph","styled","raw","link","equation"):
            if f=="raw" and fields.get("block"): self.block_raw(content,st,x,width)
            else: self._para(content,st,x,width)
