    # paragraph machinery
    def _para(self, body, st,x,w,align="left"):
        if body is None: return
        tokens=[]; flatten_inline(body,st,tokens)
        if not tokens: return
        self._render_lines(tokens,w,x,st,align=align)
        # paragraph spacing
        par_settings=self.doc.settings.get("par",{}) if isinstance(self.doc.settings,dict) else {}
        spacing=resolve_length(par_settings.get("spacing"), st.get("size",11)) if par_settings.get("spacing") else st.get("size",11)*0.55
        self.y+=spacing or 0
    def layout_paragraph_text(self,txt,st,x,w): self._para_text(txt,st,x,w)
    def _para_text(self,txt,st,x,w):
        tokens=[]; _append_text(txt,st,tokens); self._render_lines(tokens,w,x,st)
    def _render_lines(self,tokens,w,x,st,align="left"):
        lines=wrap_tokens(tokens,w)
        self._render_token_lines(lines,x,st,align=align)
    def _render_token_lines(self,lines,x,st,align="left", first_y_offset=0):
        line_h=st.get("size",11)*1.31
        for line in lines:
            self.ensure(line_h)
            self.y+=line_h
            baseline=self.y-line_h+st.get("size",11)*0.95
            lw=sum(t.width() for t in line)
            lx=x
            if align=="center": lx=x+max(0,(self.avail_w if x==self.margins["left"] else 0))
            # align calc done in _draw_line with page avail if needed
            self._draw_line(line,lx,baseline,st,align=align)
    def _draw_line(self,line,x,baseline,st,align="left"):
        # compute width for alignment relative to current block width unknown: use avail
        total=sum(t.width() for t in line)
        if align=="center": x = self.margins["left"] + (self.avail_w-total)/2
        elif align=="right": x = self.margins["left"] + self.avail_w-total
        cx=x
        # merge consecutive tokens with same style into text runs
        run=None; run_style=None; run_x=None
        def flush_run():
            if run: self.add_op(("text",run_x,baseline,run,run_style))
        for tok in line:
            if tok.kind=="space": 
                if run is not None: run+=" "; cx+=tok.width(); continue
                cx+=tok.width(); continue
            if tok.kind=="atomic":
                flush_run(); run=None
                if tok.content is not None and isinstance(tok.content,Content) and tok.content.func=="image":
                    path=resolve_image_path(tok.content.fields.get("source",""), self.root_dir, self.doc)
                    self.add_op(("image",cx,baseline-tok.style.get("size",11),tok.style.get("_w",50),tok.style.get("size",11),path or ""))
                cx+=tok.width(); continue
            if run_style is not None and tok.style==run_style:
                run+=tok.text
            else:
                flush_run(); run=tok.text; run_style=dict(tok.style); run_x=cx
            cx+=tok.width()
        flush_run()

