def do_init(parsed):
    spec_str=parsed.pos[0]; directory=parsed.pos[1] if len(parsed.pos)>1 else None
    if not spec_str.startswith("@"):
        print_error_simple("package specification must start with '@'"); return 1
    rest=spec_str[1:]
    if "/" not in rest:
        print_error_simple("package specification is missing name"); return 1
    namespace,namever=rest.split("/",1)
    if not namever:
        print_error_simple("package specification is missing name"); return 1
    if ":" in namever: name,version=namever.rsplit(":",1)
    else: name,version=namever,None
    if not name:
        print_error_simple("package specification is missing name"); return 1
    if version is None:
        print_error_simple("please specify the desired version"); return 1
    # validate version roughly semver
    parts=version.split("-")[0].split(".")
    if not parts[0].isdigit():
        print_error_simple(f"`{parts[0]}` is not a valid major version"); return 1
    if len(parts)<2 or not parts[1].isdigit():
        print_error_simple(f"`{version}` is not a valid minor version" if len(parts)>=2 else "`"+version+"` is not a valid version"); return 1
    if namespace=="preview":
        # cached preview packages location
        _cache_home=os.environ.get("XDG_CACHE_HOME") or os.path.expanduser("~/.cache")
        cache_dir=os.path.join(parsed.get("package-cache-path") or os.path.join(_cache_home,"typst","packages"), "preview", name, version)
        local_dir=cache_dir
        if not os.path.isdir(local_dir):
            print_error_simple(f"failed to fetch package index (https://packages.typst.org/preview/index.json: Dns Failed: resolve dns name 'packages.typst.org:443': failed to lookup address information: Temporary failure in name resolution)")
            return 1
        pkg_dir=local_dir
    else:
        pp=parsed.get("package-path") or package_paths()[0]
        pkg_dir=os.path.join(pp, namespace, name, version)
        if not os.path.isdir(pkg_dir):
            print_error_simple(f"package not found (searched for @{namespace}/{name}:{version})"); return 1
    toml_path=os.path.join(pkg_dir,"typst.toml")
    template_info=None
    if os.path.isfile(toml_path):
        template_info=parse_toml_template(open(toml_path,encoding="utf-8",errors="ignore").read())
    if not template_info:
        print_error_simple(f"package @{namespace}/{name}:{version} is not a template"); return 1
    tpath, entrypoint = template_info
    dest_dir=directory or name
    if os.path.exists(dest_dir):
        print_error_simple(f"project directory already exists (at {dest_dir})"); return 1
    src_dir=os.path.join(pkg_dir, tpath) if tpath else pkg_dir
    try:
        import shutil
        shutil.copytree(src_dir, dest_dir)
    except OSError as e:
        print_error_simple(f"failed to create project directory ({e})"); return 1
    sys.stdout.write(f"Successfully created new project from @{namespace}/{name}:{version} 🎉\nTo start writing, run:\n> cd {dest_dir}\n> typst watch {entrypoint}\n"); return 0
def parse_toml_template(text):
    # minimal TOML parsing for [template] path/entrypoint
    section=None; vals={}
    for line in text.splitlines():
        line=line.strip()
        if line.startswith("[") and line.endswith("]"): section=line[1:-1].strip(); continue
        if section=="template" and "=" in line:
            k,v=line.split("=",1); vals[k.strip()]=v.strip().strip('"').strip("'")
    if not vals and "template" not in text: return None
    if "[template]" not in text: return None
    return (vals.get("path","."), vals.get("entrypoint","main.typ"))

