        if o.year is not None and o.hour is None: return d.strftime("%Y-%m-%d")
        if o.year is None: return d.strftime("%H:%M:%S")
        return d.strftime("%Y-%m-%d %H:%M:%S")
    out=str(fmt)
    months=["January","February","March","April","May","June","July","August","September","October","November","December"]
    wdays=["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"]
    def repl(m):
        inner=m.group(1)
        name=inner.split()[0]
        opts=inner[len(name):]
        if name=="year": return f"{d.year:04d}" if "padding" not in opts else str(d.year)
        if name=="month":
            if "short" in opts: return months[d.month-1][:3]
            if "long" in opts: return months[d.month-1]
            if "padding: none" in opts: return str(d.month)
            return f"{d.month:02d}"
        if name=="day": return str(d.day) if "padding: none" in opts else f"{d.day:02d}"
        if name=="hour": return f"{d.hour:02d}" if "repre" not in opts else str(d.hour)
        if name=="minute": return f"{d.minute:02d}"
        if name=="second": return f"{d.second:02d}"
        if name=="weekday":
            wd=wdays[d.weekday()]
            return wd[:3] if "short" in opts else wd
        if name=="period": return "AM" if d.hour<12 else "PM"
        if name=="ordinal": return str(d.timetuple().tm_yday)
        return m.group(0)
    return re.sub(r"\\[([^\\]]+)\\]", repl, out)
'''
s=s[:old_start]+new+s[old_end:]
p.write_text(s)
